package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.api.WorkforceAttendancePolicyController;import com.rpb.reservation.workforce.attendancepolicy.AttendancePolicyService;import com.rpb.reservation.walkin.api.*;import com.rpb.reservation.walkin.auth.LocalRuntimeSecurityConfiguration;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.context.TestPropertySource;import org.springframework.test.web.servlet.MockMvc;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(WorkforceAttendancePolicyController.class) @Import({LocalRuntimeSecurityConfiguration.class,com.rpb.reservation.appgate.api.AppGateApiErrorMapper.class}) @ActiveProfiles("local") @TestPropertySource(properties="rpb.local-auth.enabled=true")
class WorkforceAttendancePolicyLocalRuntimeSecurityTest {
 @Autowired MockMvc mvc;@MockBean CurrentActorProvider actors;@MockBean AttendancePolicyService service;@MockBean com.rpb.reservation.appgate.application.AppGateService gate;@MockBean com.rpb.reservation.appgate.application.AppGateDenialAuditService denialAudit;
 @Test void exactMethodsOnly()throws Exception{when(actors.currentActor()).thenReturn(Optional.of(new CurrentActor(UUID.randomUUID(),UUID.randomUUID(),"staff",Set.of(),Set.of(),Set.of())));String base="/api/v1/stores/"+UUID.randomUUID()+"/workforce";UUID employee=UUID.randomUUID();mvc.perform(get(base+"/attendance-policy-defaults")).andExpect(status().isOk());mvc.perform(get(base+"/attendance-policy")).andExpect(status().isOk());mvc.perform(get(base+"/employees/"+employee+"/attendance-policy")).andExpect(status().isOk());for(var path:List.of("/attendance-policy-defaults/"+UUID.randomUUID(),"/employees/"+employee+"/attendance-policies/"+UUID.randomUUID()))mvc.perform(put(base+path).header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isOk());verify(service).self(any(),any());verify(service).page(any(),any(),eq(employee));verify(service).save(any(),any(),eq(employee),any(),any());mvc.perform(delete(base+"/attendance-policy-defaults/"+UUID.randomUUID())).andExpect(status().isForbidden());mvc.perform(post(base+"/attendance-policy-defaults/"+UUID.randomUUID())).andExpect(status().isForbidden());mvc.perform(put(base+"/attendance-policy/unsupported").contentType("application/json").content("{}")).andExpect(status().isForbidden());}
}
